/**
 * @private
 */
class VFCManager {

    constructor(scene, sceneModel) {
        this.sceneModel = sceneModel;
        this.entities = [];
        this.meshes = [];
        this.finalized = false;
    }

    addEntity(entity) {
        if (this.finalized) {
            throw "Already finalized";
        }
        this.entities.push(entity);
    }

    addMesh(mesh) {
        if (this.finalized) {
            throw "Already finalized";
        }
        this.meshes.push(mesh);
    }

    finalize(fnForceFinalizeLayer) {
        if (this.finalized) {
            throw "Already finalized";
        }
        this.finalized = true;
        this.VFCState = new VFCState();
        this.VFCState.initializeVFCState(this.entities, this.meshes);
        this.VFCState.finalize(this.sceneModel, fnForceFinalizeLayer);
        this._onSceneRendering = this.sceneModel.scene.on("rendering", () => this.applyViewFrustumCulling.call(this));
    }

    applyViewFrustumCulling() {
        if (!this.finalized) {
            return;
        }
        this.VFCState.applyViewFrustumCulling(this.sceneModel);
    }

    destroy() {
        if (this.finalized) {
            this.sceneModel.off(this._onSceneRendering);
        }
    }
}

/**
 * Manages view frustum culling (VFC) for {@link SceneModel} implementations.
 */
class VFC extends Component {

    /** @private */
    constructor(scene, cfg = {}) {
        super(scene, cfg);
        this._scene = scene;
        this._vfcManagers = {};
        this._vfcManagerList = [];
        this.enabled = cfg.enabled;
        this._init();
    }

    _init() {
        this._scene.on("rendering", () => { // Apply VFC-culling before rendering the scene
            for (let i = 0, len = this._vfcManagerList.length; i < len; i++) {
                this._vfcManagerList[i].applyViewFrustumCulling();
            }
        });
    }

    /**
     * Sets whether view frustum culling (VFC) is enabled for the {@link Scene}.
     *
     * Default value is ````false````.
     *
     * @type {Boolean}
     */
    set enabled(value) {
        value = !!value;
        if (this._enabled === value) {
            return;
        }
        this._enabled = value;
        this.glRedraw();
    }

    /**
     * Gets whether view frustum culling (VFC) is enabled for the {@link Scene}.
     *
     * Default value is ````false````.
     *
     * @type {Boolean}
     */
    get enabled() {
        return this._enabled;
    }

    /**
     * Called within SceneModel constructors
     * @private
     */
    getVFCManager(sceneModel) {
        const vfcManager = new VFCManager(this.scene, sceneModel);
        this._vfcManagers[vfcManager.id] = vfcManager;
        this._vfcManagerList = Object.values(this._vfcManagers);
        return vfcManager;
    }

    /**
     * Called within SceneModel destructors
     * @private
     */
    putVFCManager(vfcManager) {
        delete this._vfcManagers[vfcManager.id];
        this._vfcManagerList = Object.values(this._vfcManagers);
    }

    /**
     * Destroys this component.
     *
     * @private
     */
    destroy() {
        super.destroy();
    }
}

// Cached vars to avoid garbage collection

function getEntityIDMap(scene, entityIds) {
    const map = {};
    let entityId;
    let entity;
    for (let i = 0, len = entityIds.length; i < len; i++) {
        entityId = entityIds[i];
        entity = scene.component[entityId];
        if (!entity) {
            scene.warn("pick(): Component not found: " + entityId);
            continue;
        }
        if (!entity.isEntity) {
            scene.warn("pick(): Component is not an Entity: " + entityId);
            continue;
        }
        map[entityId] = true;
    }
    return map;
}

